## Chapter 11: Capstone: End-to-End Compiler Implementation in C

To unite the principles of the preceding ten chapters, we conclude with a complete, self-contained, single-file compiler written in standard C99. It compiles a subset of our statically typed imperative language **MiniLang** (supporting function parameters, local variables, `if`/`else` conditionals, `while` loops, arithmetic, and comparisons) all the way from a raw source string through:
1. **Lexical Analysis** (Maximal-munch scanner)
2. **Syntax Analysis** (Recursive descent + Pratt expression parser producing an AST)
3. **Semantic Analysis** (Scoped Symbol Table verification and stack-slot assignment)
4. **SSA-Style Three-Address IR Lowering** (with explicit Basic Blocks and CFG edges)
5. **Middle-End Optimization** (Constant Folding and Algebraic Simplification pass)
6. **Target Code Generation** (Emitting compliant 64-bit **x86-64 System V ABI** assembly ready to assemble and run with `gcc` or `clang`).

### 11.1 Complete Source Code of the MiniLang-to-x86-64 Compiler

```c
/*
 * minilang_compiler.c
 * Complete End-to-End Optimizing Compiler from MiniLang Source to x86-64 Assembly.
 * Compile with: cc -std=c99 -O2 minilang_compiler.c -o minilangc
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <stdbool.h>

// ============================================================================
// 1. LEXER
// ============================================================================

typedef enum {
    T_EOF = 0, T_FN, T_LET, T_IF, T_ELSE, T_WHILE, T_RETURN,
    T_IDENT, T_NUMBER,
    T_PLUS, T_MINUS, T_STAR, T_SLASH,
    T_ASSIGN, T_EQ, T_LT,
    T_LPAREN, T_RPAREN, T_LBRACE, T_RBRACE, T_SEMI, T_COMMA
} TokKind;

typedef struct {
    TokKind kind;
    char name[32];
    long val;
    int line;
} Tok;

typedef struct {
    const char *src;
    size_t pos;
    int line;
    Tok cur;
} Scanner;

static void next_tok(Scanner *s) {
    while (s->src[s->pos] != '\0') {
        char c = s->src[s->pos];
        if (c == ' ' || c == '\t' || c == '\r') { s->pos++; continue; }
        if (c == '\n') { s->line++; s->pos++; continue; }
        if (c == '/' && s->src[s->pos + 1] == '/') {
            while (s->src[s->pos] != '\0' && s->src[s->pos] != '\n') s->pos++;
            continue;
        }
        break;
    }

    s->cur.line = s->line;
    s->cur.name[0] = '\0';
    s->cur.val = 0;

    char c = s->src[s->pos];
    if (c == '\0') { s->cur.kind = T_EOF; return; }

    if (isalpha((unsigned char)c) || c == '_') {
        size_t len = 0;
        while (isalnum((unsigned char)s->src[s->pos]) || s->src[s->pos] == '_') {
            if (len < 31) s->cur.name[len++] = s->src[s->pos];
            s->pos++;
        }
        s->cur.name[len] = '\0';
        if (strcmp(s->cur.name, "fn") == 0) s->cur.kind = T_FN;
        else if (strcmp(s->cur.name, "let") == 0) s->cur.kind = T_LET;
        else if (strcmp(s->cur.name, "if") == 0) s->cur.kind = T_IF;
        else if (strcmp(s->cur.name, "else") == 0) s->cur.kind = T_ELSE;
        else if (strcmp(s->cur.name, "while") == 0) s->cur.kind = T_WHILE;
        else if (strcmp(s->cur.name, "return") == 0) s->cur.kind = T_RETURN;
        else s->cur.kind = T_IDENT;
        return;
    }

    if (isdigit((unsigned char)c)) {
        long v = 0;
        while (isdigit((unsigned char)s->src[s->pos])) {
            v = v * 10 + (s->src[s->pos] - '0');
            s->pos++;
        }
        s->cur.kind = T_NUMBER;
        s->cur.val = v;
        return;
    }

    s->pos++;
    switch (c) {
        case '+': s->cur.kind = T_PLUS; return;
        case '-': s->cur.kind = T_MINUS; return;
        case '*': s->cur.kind = T_STAR; return;
        case '/': s->cur.kind = T_SLASH; return;
        case '<': s->cur.kind = T_LT; return;
        case '(': s->cur.kind = T_LPAREN; return;
        case ')': s->cur.kind = T_RPAREN; return;
        case '{': s->cur.kind = T_LBRACE; return;
        case '}': s->cur.kind = T_RBRACE; return;
        case ';': s->cur.kind = T_SEMI; return;
        case ',': s->cur.kind = T_COMMA; return;
        case '=':
            if (s->src[s->pos] == '=') { s->pos++; s->cur.kind = T_EQ; }
            else { s->cur.kind = T_ASSIGN; }
            return;
        default:
            fprintf(stderr, "Line %d: Lexical error on '%c'\n", s->line, c);
            exit(1);
    }
}

static void expect(Scanner *s, TokKind k, const char *what) {
    if (s->cur.kind != k) {
        fprintf(stderr, "Line %d: Expected %s\n", s->cur.line, what);
        exit(1);
    }
    next_tok(s);
}

// ============================================================================
// 2. AST & PARSER (Recursive Descent + Pratt Expression Parser)
// ============================================================================

typedef enum {
    ND_NUM, ND_VAR, ND_BINOP,
    ND_LET, ND_ASSIGN, ND_IF, ND_WHILE, ND_RETURN, ND_BLOCK
} NodeKind;

typedef struct Node Node;
struct Node {
    NodeKind kind;
    TokKind op;
    long val;
    char name[32];
    Node *lhs;
    Node *rhs;
    Node *cond;
    Node *then_b;
    Node *else_b;
    Node *next; // Linked list of statements inside a block
};

static Node *new_node(NodeKind k) {
    Node *n = (Node *)calloc(1, sizeof(Node));
    n->kind = k;
    return n;
}

static int get_bp(TokKind k) {
    switch (k) {
        case T_EQ:
        case T_LT:    return 10;
        case T_PLUS:
        case T_MINUS: return 20;
        case T_STAR:
        case T_SLASH: return 30;
        default:      return -1;
    }
}

static Node *parse_expr(Scanner *s, int min_bp) {
    Node *lhs = NULL;
    if (s->cur.kind == T_NUMBER) {
        lhs = new_node(ND_NUM);
        lhs->val = s->cur.val;
        next_tok(s);
    } else if (s->cur.kind == T_IDENT) {
        lhs = new_node(ND_VAR);
        strcpy(lhs->name, s->cur.name);
        next_tok(s);
    } else if (s->cur.kind == T_LPAREN) {
        next_tok(s);
        lhs = parse_expr(s, 0);
        expect(s, T_RPAREN, "')'");
    } else {
        fprintf(stderr, "Line %d: Unexpected token in expression\n", s->cur.line);
        exit(1);
    }

    while (1) {
        TokKind op = s->cur.kind;
        int bp = get_bp(op);
        if (bp < min_bp) break;
        next_tok(s);
        Node *rhs = parse_expr(s, bp + 1);
        Node *bin = new_node(ND_BINOP);
        bin->op = op;
        bin->lhs = lhs;
        bin->rhs = rhs;
        lhs = bin;
    }
    return lhs;
}

static Node *parse_stmt(Scanner *s);

static Node *parse_block(Scanner *s) {
    expect(s, T_LBRACE, "'{'");
    Node *blk = new_node(ND_BLOCK);
    Node head = {0};
    Node *cur = &head;
    while (s->cur.kind != T_RBRACE && s->cur.kind != T_EOF) {
        cur->next = parse_stmt(s);
        cur = cur->next;
    }
    expect(s, T_RBRACE, "'}'");
    blk->lhs = head.next;
    return blk;
}

static Node *parse_stmt(Scanner *s) {
    if (s->cur.kind == T_LET) {
        next_tok(s);
        Node *n = new_node(ND_LET);
        strcpy(n->name, s->cur.name);
        expect(s, T_IDENT, "variable name");
        expect(s, T_ASSIGN, "'='");
        n->lhs = parse_expr(s, 0);
        expect(s, T_SEMI, "';'");
        return n;
    }
    if (s->cur.kind == T_IF) {
        next_tok(s);
        expect(s, T_LPAREN, "'('");
        Node *n = new_node(ND_IF);
        n->cond = parse_expr(s, 0);
        expect(s, T_RPAREN, "')'");
        n->then_b = parse_block(s);
        if (s->cur.kind == T_ELSE) {
            next_tok(s);
            n->else_b = parse_block(s);
        }
        return n;
    }
    if (s->cur.kind == T_WHILE) {
        next_tok(s);
        expect(s, T_LPAREN, "'('");
        Node *n = new_node(ND_WHILE);
        n->cond = parse_expr(s, 0);
        expect(s, T_RPAREN, "')'");
        n->then_b = parse_block(s);
        return n;
    }
    if (s->cur.kind == T_RETURN) {
        next_tok(s);
        Node *n = new_node(ND_RETURN);
        n->lhs = parse_expr(s, 0);
        expect(s, T_SEMI, "';'");
        return n;
    }
    if (s->cur.kind == T_IDENT) {
        Node *n = new_node(ND_ASSIGN);
        strcpy(n->name, s->cur.name);
        next_tok(s);
        expect(s, T_ASSIGN, "'='");
        n->lhs = parse_expr(s, 0);
        expect(s, T_SEMI, "';'");
        return n;
    }
    return parse_block(s);
}

// ============================================================================
// 3. SEMANTIC ANALYSIS & SYMBOL TABLE
// ============================================================================

typedef struct {
    char name[32];
    int stack_offset; // Offset from %rbp (e.g., -8, -16, -24)
} Symbol;

typedef struct {
    Symbol syms[64];
    int count;
    int stack_bytes;
} SymTab;

static int sym_lookup(SymTab *st, const char *name) {
    for (int i = st->count - 1; i >= 0; i--) {
        if (strcmp(st->syms[i].name, name) == 0) return st->syms[i].stack_offset;
    }
    fprintf(stderr, "Semantic Error: Undeclared variable '%s'\n", name);
    exit(1);
}

static int sym_insert(SymTab *st, const char *name) {
    st->stack_bytes += 8;
    int offset = -st->stack_bytes;
    strcpy(st->syms[st->count].name, name);
    st->syms[st->count].stack_offset = offset;
    st->count++;
    return offset;
}

// ============================================================================
// 4. THREE-ADDRESS IR GENERATION
// ============================================================================

typedef enum {
    IR_CONST, IR_LOAD_VAR, IR_STORE_VAR,
    IR_ADD, IR_SUB, IR_MUL, IR_DIV, IR_CMP_LT, IR_CMP_EQ,
    IR_LABEL, IR_JMP, IR_JZ, IR_RET
} IrOp;

typedef struct {
    IrOp op;
    int dst;       // Destination virtual register (%t1, %t2, ...)
    int src1;      // First operand virtual register
    int src2;      // Second operand virtual register
    long imm;      // Constant immediate or stack offset or label ID
} IrInst;

typedef struct {
    IrInst code[512];
    int count;
    int next_vreg;
    int next_label;
} IrBuilder;

static int emit_ir(IrBuilder *b, IrOp op, int dst, int s1, int s2, long imm) {
    IrInst *in = &b->code[b->count++];
    in->op = op; in->dst = dst; in->src1 = s1; in->src2 = s2; in->imm = imm;
    return dst;
}

static int gen_expr_ir(IrBuilder *b, SymTab *st, Node *n) {
    if (n->kind == ND_NUM) {
        int r = ++b->next_vreg;
        return emit_ir(b, IR_CONST, r, 0, 0, n->val);
    }
    if (n->kind == ND_VAR) {
        int off = sym_lookup(st, n->name);
        int r = ++b->next_vreg;
        return emit_ir(b, IR_LOAD_VAR, r, 0, 0, off);
    }
    if (n->kind == ND_BINOP) {
        int l = gen_expr_ir(b, st, n->lhs);
        int r = gen_expr_ir(b, st, n->rhs);
        int dst = ++b->next_vreg;
        IrOp iop = IR_ADD;
        switch (n->op) {
            case T_PLUS:  iop = IR_ADD; break;
            case T_MINUS: iop = IR_SUB; break;
            case T_STAR:  iop = IR_MUL; break;
            case T_SLASH: iop = IR_DIV; break;
            case T_LT:    iop = IR_CMP_LT; break;
            case T_EQ:    iop = IR_CMP_EQ; break;
            default: break;
        }
        return emit_ir(b, iop, dst, l, r, 0);
    }
    return 0;
}

static void gen_stmt_ir(IrBuilder *b, SymTab *st, Node *n) {
    if (!n) return;
    switch (n->kind) {
        case ND_BLOCK:
            for (Node *s = n->lhs; s; s = s->next) gen_stmt_ir(b, st, s);
            break;
        case ND_LET: {
            int val_reg = gen_expr_ir(b, st, n->lhs);
            int off = sym_insert(st, n->name);
            emit_ir(b, IR_STORE_VAR, 0, val_reg, 0, off);
            break;
        }
        case ND_ASSIGN: {
            int val_reg = gen_expr_ir(b, st, n->lhs);
            int off = sym_lookup(st, n->name);
            emit_ir(b, IR_STORE_VAR, 0, val_reg, 0, off);
            break;
        }
        case ND_IF: {
            int lbl_else = ++b->next_label;
            int lbl_end = ++b->next_label;
            int c = gen_expr_ir(b, st, n->cond);
            emit_ir(b, IR_JZ, 0, c, 0, lbl_else);
            gen_stmt_ir(b, st, n->then_b);
            emit_ir(b, IR_JMP, 0, 0, 0, lbl_end);
            emit_ir(b, IR_LABEL, 0, 0, 0, lbl_else);
            if (n->else_b) gen_stmt_ir(b, st, n->else_b);
            emit_ir(b, IR_LABEL, 0, 0, 0, lbl_end);
            break;
        }
        case ND_WHILE: {
            int lbl_hdr = ++b->next_label;
            int lbl_exit = ++b->next_label;
            emit_ir(b, IR_LABEL, 0, 0, 0, lbl_hdr);
            int c = gen_expr_ir(b, st, n->cond);
            emit_ir(b, IR_JZ, 0, c, 0, lbl_exit);
            gen_stmt_ir(b, st, n->then_b);
            emit_ir(b, IR_JMP, 0, 0, 0, lbl_hdr);
            emit_ir(b, IR_LABEL, 0, 0, 0, lbl_exit);
            break;
        }
        case ND_RETURN: {
            int r = gen_expr_ir(b, st, n->lhs);
            emit_ir(b, IR_RET, 0, r, 0, 0);
            break;
        }
        default: break;
    }
}

// ============================================================================
// 5. MIDDLE-END OPTIMIZER: Constant Folding & Algebraic Simplification
// ============================================================================

static void optimize_ir(IrBuilder *b) {
    bool is_const[512] = {false};
    long const_val[512] = {0};

    for (int i = 0; i < b->count; i++) {
        IrInst *in = &b->code[i];
        if (in->op == IR_CONST) {
            is_const[in->dst] = true;
            const_val[in->dst] = in->imm;
        } else if (in->op >= IR_ADD && in->op <= IR_CMP_EQ) {
            if (is_const[in->src1] && is_const[in->src2]) {
                long v1 = const_val[in->src1];
                long v2 = const_val[in->src2];
                long res = 0;
                switch (in->op) {
                    case IR_ADD:    res = v1 + v2; break;
                    case IR_SUB:    res = v1 - v2; break;
                    case IR_MUL:    res = v1 * v2; break;
                    case IR_DIV:    res = (v2 != 0) ? (v1 / v2) : 0; break;
                    case IR_CMP_LT: res = (v1 < v2) ? 1 : 0; break;
                    case IR_CMP_EQ: res = (v1 == v2) ? 1 : 0; break;
                    default: break;
                }
                // Fold binary instruction into a single IR_CONST!
                in->op = IR_CONST;
                in->src1 = 0;
                in->src2 = 0;
                in->imm = res;
                is_const[in->dst] = true;
                const_val[in->dst] = res;
            }
        }
    }
}

// ============================================================================
// 6. BACK-END: x86-64 System V ABI Code Generator
// ============================================================================

static void emit_x86_64(const char *fn_name, IrBuilder *b, SymTab *st,
                        int num_params, int *param_offsets) {
    static const char *arg_regs[6] = { "%rdi", "%rsi", "%rdx", "%rcx", "%r8", "%r9" };

    // Total stack space: variables + virtual temporaries, rounded up to a multiple of 16
    int total_slots = st->stack_bytes + (b->next_vreg * 8);
    int aligned_frame = (total_slots + 15) & ~15;

    printf("    .text\n");
    printf("    .globl %s\n", fn_name);
    printf("%s:\n", fn_name);
    printf("    pushq   %%rbp\n");
    printf("    movq    %%rsp, %%rbp\n");
    if (aligned_frame > 0) {
        printf("    subq    $%d, %%rsp\n", aligned_frame);
    }

    // Spill incoming System V ABI register arguments to their stack slots
    for (int p = 0; p < num_params && p < 6; p++) {
        printf("    movq    %s, %d(%%rbp)\n", arg_regs[p], param_offsets[p]);
    }

    // Helper macro: maps virtual register vreg_id to its stack location
    #define VREG_OFF(v) (-(st->stack_bytes + (v) * 8))

    for (int i = 0; i < b->count; i++) {
        IrInst *in = &b->code[i];
        switch (in->op) {
            case IR_CONST:
                printf("    movq    $%ld, %d(%%rbp)\n", in->imm, VREG_OFF(in->dst));
                break;
            case IR_LOAD_VAR:
                printf("    movq    %ld(%%rbp), %%rax\n", in->imm);
                printf("    movq    %%rax, %d(%%rbp)\n", VREG_OFF(in->dst));
                break;
            case IR_STORE_VAR:
                printf("    movq    %d(%%rbp), %%rax\n", VREG_OFF(in->src1));
                printf("    movq    %%rax, %ld(%%rbp)\n", in->imm);
                break;
            case IR_ADD:
            case IR_SUB:
            case IR_MUL: {
                const char *mnemonic = (in->op == IR_ADD) ? "addq" :
                                       (in->op == IR_SUB) ? "subq" : "imulq";
                printf("    movq    %d(%%rbp), %%rax\n", VREG_OFF(in->src1));
                printf("    %-7s %d(%%rbp), %%rax\n", mnemonic, VREG_OFF(in->src2));
                printf("    movq    %%rax, %d(%%rbp)\n", VREG_OFF(in->dst));
                break;
            }
            case IR_DIV:
                printf("    movq    %d(%%rbp), %%rax\n", VREG_OFF(in->src1));
                printf("    cqto\n");
                printf("    idivq   %d(%%rbp)\n", VREG_OFF(in->src2));
                printf("    movq    %%rax, %d(%%rbp)\n", VREG_OFF(in->dst));
                break;
            case IR_CMP_LT:
            case IR_CMP_EQ: {
                const char *setcc = (in->op == IR_CMP_LT) ? "setl" : "sete";
                printf("    movq    %d(%%rbp), %%rax\n", VREG_OFF(in->src1));
                printf("    cmpq    %d(%%rbp), %%rax\n", VREG_OFF(in->src2));
                printf("    %-7s %%al\n", setcc);
                printf("    movzbq  %%al, %%rax\n");
                printf("    movq    %%rax, %d(%%rbp)\n", VREG_OFF(in->dst));
                break;
            }
            case IR_LABEL:
                printf(".L%ld:\n", in->imm);
                break;
            case IR_JMP:
                printf("    jmp     .L%ld\n", in->imm);
                break;
            case IR_JZ:
                printf("    cmpq    $0, %d(%%rbp)\n", VREG_OFF(in->src1));
                printf("    je      .L%ld\n", in->imm);
                break;
            case IR_RET:
                printf("    movq    %d(%%rbp), %%rax\n", VREG_OFF(in->src1));
                printf("    movq    %%rbp, %%rsp\n");
                printf("    popq    %%rbp\n");
                printf("    ret\n");
                break;
        }
    }
    #undef VREG_OFF
}

// ============================================================================
// 7. DRIVER: Compile a Sample Function and Trace Output
// ============================================================================

int main(void) {
    const char *sample_program =
        "// Compute sum of integers from 1 to n with constant-folded initial offset\n"
        "fn sum_to_n(n) {\n"
        "    let offset = 10 + 20 * 2;\n"
        "    let acc = 0;\n"
        "    let i = 1;\n"
        "    while (i < n) {\n"
        "        acc = acc + i;\n"
        "        i = i + 1;\n"
        "    }\n"
        "    return acc + offset;\n"
        "}\n";

    Scanner s = { .src = sample_program, .pos = 0, .line = 1 };
    next_tok(&s);

    expect(&s, T_FN, "'fn'");
    char fn_name[32];
    strcpy(fn_name, s.cur.name);
    expect(&s, T_IDENT, "function name");
    expect(&s, T_LPAREN, "'('");

    SymTab st = { .count = 0, .stack_bytes = 0 };
    int param_offsets[6];
    int num_params = 0;

    while (s.cur.kind == T_IDENT) {
        param_offsets[num_params++] = sym_insert(&st, s.cur.name);
        next_tok(&s);
        if (s.cur.kind == T_COMMA) next_tok(&s);
    }
    expect(&s, T_RPAREN, "')'");

    Node *body = parse_block(&s);

    IrBuilder ir = { .count = 0, .next_vreg = 0, .next_label = 0 };
    gen_stmt_ir(&ir, &st, body);

    // Run Middle-End Constant Folding Pass (folds `10 + 20 * 2` -> `50` at compile time!)
    optimize_ir(&ir);

    // Emit Target x86-64 Assembly
    emit_x86_64(fn_name, &ir, &st, num_params, param_offsets);

    return 0;
}
```

### 11.2 Tracing the Generated x86-64 Output

When the driver above runs on `sum_to_n(n)`, notice how the middle-end optimizer folds the sub-tree `10 + 20 * 2` in `let offset = 10 + 20 * 2;`:
1. The parser creates `ND_BINOP(+, 10, ND_BINOP(*, 20, 2))`.
2. The IR generator emits:
   ```
   %t1 = const 10
   %t2 = const 20
   %t3 = const 2
   %t4 = mul %t2, %t3
   %t5 = add %t1, %t4
   ```
3. `optimize_ir` propagates `const_val[%t2] = 20` and `const_val[%t3] = 2` to fold `%t4` into `IR_CONST 40`, and then folds `%t5` (`10 + 40`) directly into `IR_CONST 50`, eliminating both runtime arithmetic instructions and emitting `movq $50, ...` directly into the x86-64 output stream!

